final class SchoolPayroll {
 public function __construct(public PayrollAccess $pay){}
 public function salary(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.manage');$p=$this->pay->staff($r,$d['staff_profile_id'],false,true);$latest=DB::table('payroll_items as i')->join('payroll_runs as r','r.id','=','i.payroll_run_id')->where('i.school_id',$sid)->where('i.staff_profile_id',$p->id)->where('r.status','approved')->max('r.period');if($latest&&$d['starts_on']<=CarbonImmutable::parse($latest)->endOfMonth()->toDateString())$this->pay->fail('Salary changes cannot rewrite an approved payroll month. Request a payroll adjustment.');$end=$d['ends_on']??'9999-12-31';$overlap=DB::table('salary_structures')->where('school_id',$sid)->where('staff_profile_id',$p->id)->where('status','active')->where('starts_on','<=',$end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$d['starts_on']))->get();if($overlap->count()){if(!$d['replace_previous']||$overlap->count()!==1||$overlap[0]->starts_on>=$d['starts_on']||$overlap[0]->ends_on!==null)$this->pay->fail('Salary effective dates overlap. Explicitly close the previous open-ended structure or choose non-overlapping dates.');DB::table('salary_structures')->where('school_id',$sid)->where('id',$overlap[0]->id)->update(['ends_on'=>CarbonImmutable::parse($d['starts_on'])->subDay()->toDateString(),'updated_at'=>now()]);}if(collect($d['items'])->where('kind','basic')->count()!==1)$this->pay->fail('Add exactly one basic salary component.');$gross=0;$deduct=0;foreach($d['items'] as $item){$n=$this->pay->cents($item['amount']);if($item['kind']==='basic'&&!$n)$this->pay->fail('Basic salary must be positive.');if($item['kind']==='deduction')$deduct+=$n;else $gross+=$n;}if($deduct>$gross)$this->pay->fail('Fixed deductions cannot exceed gross salary.');$id=DB::table('salary_structures')->insertGetId(['school_id'=>$sid,'staff_profile_id'=>$p->id,'starts_on'=>$d['starts_on'],'ends_on'=>$d['ends_on']??null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);foreach($d['items'] as $item)DB::table('salary_structure_items')->insert($item+['school_id'=>$sid,'salary_structure_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.salary_created','salary_structures',$id,$d);return ['id'=>$id,'message'=>'Effective salary structure saved.'];});}
 public function salaries(Request $r,int $staff):array{[$sid,,$campuses]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);$p=$this->pay->staff($r,$staff);$structures=DB::table('salary_structures')->where('school_id',$sid)->where('staff_profile_id',$p->id)->whereExists(function($q)use($sid,$campuses){$q->selectRaw('1')->from('staff_employments as e')->where('e.school_id',$sid)->whereColumn('e.staff_profile_id','salary_structures.staff_profile_id')->whereIn('e.campus_id',$campuses)->where(fn($q)=>$q->whereNull('salary_structures.ends_on')->orWhereColumn('e.starts_on','<=','salary_structures.ends_on'))->where(fn($q)=>$q->whereNull('e.ends_on')->orWhereColumn('e.ends_on','>=','salary_structures.starts_on'));})->orderByDesc('starts_on')->get();$components=DB::table('salary_structure_items')->where('school_id',$sid)->whereIn('salary_structure_id',$structures->pluck('id'))->get()->groupBy('salary_structure_id');foreach($structures as $s)$s->items=$components->get($s->id)??collect();return ['staff'=>$p,'structures'=>$structures];}
 public function policy(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.approve');$this->pay->campus($r,$d['campus_id'],true);if(substr($d['starts_on'],-2)!=='01')$this->pay->fail('Payroll policies take effect on the first day of a month.');if(DB::table('payroll_runs')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->where('status','approved')->where('period','>=',$d['starts_on'])->exists())$this->pay->fail('A policy cannot rewrite an approved payroll month. Create a later effective version.');if(DB::table('payroll_policies')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->where('starts_on',$d['starts_on'])->exists())$this->pay->fail('A policy version already starts on this date. Choose another future effective month.');$version=(int)DB::table('payroll_policies')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->max('version')+1;$id=DB::table('payroll_policies')->insertGetId(['school_id'=>$sid,'campus_id'=>$d['campus_id'],'starts_on'=>$d['starts_on'],'version'=>$version,'rules'=>json_encode($d['rules']),'created_by'=>$this->pay->access->membership($r)->id,'created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.policy_created','payroll_policies',$id,$d);return ['message'=>'Payroll policy version created.','id'=>$id];});}
 public function advanceBalance(int $sid,object $advance):int{$recovered=(int)DB::table('advance_recoveries')->where('school_id',$sid)->where('staff_advance_id',$advance->id)->selectRaw('COALESCE(SUM(amount)*100,0) as n')->value('n');$restored=(int)DB::table('payroll_adjustments as a')->join('advance_recoveries as r','r.id','=','a.advance_recovery_id')->where('a.school_id',$sid)->where('r.staff_advance_id',$advance->id)->where('a.kind','recovery_refund')->where('a.status','approved')->selectRaw('COALESCE(SUM(a.amount)*100,0) as n')->value('n');$out=$this->pay->cents($advance->amount)-$recovered+$restored;if($out<0||$out>$this->pay->cents($advance->amount))$this->pay->fail('A legacy advance recovery balance needs reconciliation.');return $out;}
 public function preview(Request $r,int $campus,string $month,?int $ignoreRun=null):array{[$sid]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);$c=$this->pay->campus($r,$campus,true);[$start,$end,$days]=$this->pay->month($month);if($end>$this->pay->today())$this->pay->fail('Run payroll for a completed month. Current-month payments should be recorded as approved advances.');$existing=DB::table('payroll_runs')->where('school_id',$sid)->where('campus_id',$campus)->where('period',$start)->orderByDesc('revision')->first();if($existing&&$existing->status==='approved')$this->pay->fail('This campus/month already has approved payroll. Open it from history; corrections use adjustments.');if($existing&&$existing->revision!==1)$this->pay->fail('Legacy payroll revisions require reconciliation before recalculation.');$policy=DB::table('payroll_policies')->where('school_id',$sid)->where('campus_id',$campus)->where('starts_on','<=',$start)->orderByDesc('starts_on')->first();if(!$policy)$this->pay->fail('Create an explicit fixed-pay or attendance-linked policy for this month first.');$rules=json_decode($policy->rules,true);if(!in_array($rules['mode']??null,['fixed','attendance'],true))$this->pay->fail('Unsupported payroll policy.');$jobs=DB::table('staff_employments')->where('school_id',$sid)->where('campus_id',$campus)->where('starts_on','<=',$end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$start))->orderBy('staff_profile_id')->orderBy('starts_on')->get()->groupBy('staff_profile_id');if(!$jobs->count())$this->pay->fail('No dated staff appointments cover this campus/month.');$school=DB::table('schools')->where('id',$sid)->first();$rows=[];$grossTotal=0;$deductTotal=0;$recoverTotal=0;$netTotal=0;
  foreach($jobs as $staffId=>$appointments){$p=$this->pay->staff($r,(int)$staffId);if(DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$staffId)->where('campus_id','<>',$campus)->where('starts_on','<=',$end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$start))->exists())$this->pay->fail($p->employee_no.': one payroll campus per month is required. Review transfer dates.');if(DB::table('payroll_items as i')->join('payroll_runs as r','r.id','=','i.payroll_run_id')->where('i.school_id',$sid)->where('i.staff_profile_id',$staffId)->where('r.status','approved')->where('r.period','>=',$start)->when($ignoreRun,fn($q)=>$q->where('r.id','<>',$ignoreRun))->exists())$this->pay->fail($p->employee_no.': an approved payroll already covers this or a later month. Process months chronologically; corrections use adjustments.');$structures=DB::table('salary_structures')->where('school_id',$sid)->where('staff_profile_id',$staffId)->where('status','active')->where('starts_on','<=',$end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$start))->orderBy('starts_on')->get();$items=DB::table('salary_structure_items')->where('school_id',$sid)->whereIn('salary_structure_id',$structures->pluck('id'))->orderBy('id')->get()->groupBy('salary_structure_id');$attendance=DB::table('staff_attendance_records')->where('school_id',$sid)->where('staff_profile_id',$staffId)->whereBetween('attendance_date',[$start,$end])->orderBy('attendance_date')->get()->keyBy('attendance_date');$leaves=DB::table('leave_requests')->where('school_id',$sid)->where('staff_profile_id',$staffId)->where('status','approved')->where('starts_on','<=',$end)->where('ends_on','>=',$start)->orderBy('id')->get()->keyBy('id');$segments=[];$counts=['present'=>0,'absent'=>0,'late'=>0,'paid_leave'=>0,'unpaid_leave'=>0,'unmarked'=>0,'working_days'=>0,'calendar_days'=>0];$attendanceDeduct=0;$lateCount=0;$sourceDays=[];
   for($date=CarbonImmutable::parse($start);$date->toDateString()<=$end;$date=$date->addDay()){$key=$date->toDateString();$covered=$appointments->filter(fn($j)=>$j->starts_on<=$key&&($j->ends_on===null||$j->ends_on>=$key));if(!$covered->count())continue;if($covered->count()!==1)$this->pay->fail($p->employee_no.': overlapping appointments.');$salary=$structures->filter(fn($s)=>$s->starts_on<=$key&&($s->ends_on===null||$s->ends_on>=$key));if($salary->count()!==1)$this->pay->fail($p->employee_no.': exactly one salary structure must cover '.$key.'.');$s=$salary->first();$components=$items->get($s->id)??collect();if($components->where('kind','basic')->count()!==1)$this->pay->fail($p->employee_no.': salary needs one basic component.');$segments[$s->id]=($segments[$s->id]??0)+1;$counts['calendar_days']++;$work=in_array($date->dayOfWeekIso,array_map('intval',$rules['weekdays']??[]),true);if(!$work)continue;$counts['working_days']++;$a=$attendance->get($key);if(!$a)$counts['unmarked']++;else{if($a->campus_id!==$campus)$this->pay->fail($p->employee_no.': attendance campus conflicts with appointment.');if($a->status==='leave'){$leave=$leaves->get($a->leave_request_id);if(!$leave||$leave->starts_on>$key||$leave->ends_on<$key)$this->pay->fail($p->employee_no.': approved leave linkage needs review on '.$key.'.');if(!in_array($leave->leave_type,['paid','unpaid'],true))$this->pay->fail('Legacy leave type requires paid/unpaid classification review.');$counts[$leave->leave_type==='paid'?'paid_leave':'unpaid_leave']++;}else $counts[$a->status]++;}$sourceDays[]=[$key,$a?->id,$a?->lock_version,$a?->status,$a?->leave_request_id];if($rules['mode']==='attendance'){if(!$a)$this->pay->fail($p->employee_no.': staff attendance is unmarked on '.$key.'. No deductions were inferred.');$basis=0;foreach($components as $component)if($component->kind==='basic'||($rules['deduction_basis']==='gross'&&$component->kind==='allowance'))$basis+=$this->pay->cents($component->amount);$rate=$this->pay->ratio($basis,1,$days);if($a->status==='absent'&&$rules['deduct_absence'])$attendanceDeduct+=$rate;if($a->status==='leave'&&$leaves[$a->leave_request_id]->leave_type==='unpaid'&&$rules['deduct_unpaid_leave'])$attendanceDeduct+=$rate;if($a->status==='late'){$lateCount++;if($rules['late_per_day']>0&&$lateCount%$rules['late_per_day']===0)$attendanceDeduct+=$rate;}}}
   $components=[];$gross=0;$deduct=0;foreach($segments as $structure=>$eligibleDays){foreach($items->get($structure)??[] as $component){$amount=$this->pay->ratio($this->pay->cents($component->amount),$eligibleDays,$days);$components[]=['name'=>$component->name.' ('.$eligibleDays.'/'.$days.' days)','kind'=>$component->kind,'amount'=>$this->pay->money($amount)];if($component->kind==='deduction')$deduct+=$amount;else $gross+=$amount;}}if($attendanceDeduct){$deduct+=$attendanceDeduct;$components[]=['name'=>'Reviewed attendance deduction','kind'=>'attendance','amount'=>$this->pay->money($attendanceDeduct)];}if($deduct>$gross)$this->pay->fail($p->employee_no.': deductions exceed prorated gross salary.');$available=$gross-$deduct;$plans=[];$recover=0;$advances=DB::table('staff_advances')->where('school_id',$sid)->where('staff_profile_id',$staffId)->where('status','paid')->where('paid_on','<',$start)->orderBy('paid_on')->orderBy('id')->get();foreach($advances as $advance){if(!$advance->campus_id||!$advance->requested_on)$this->pay->fail('A legacy staff advance requires review before recovery.');$balance=$this->advanceBalance($sid,$advance);$amount=min($balance,$this->pay->cents($advance->monthly_recovery),$available-$recover);if($amount>0){$plans[]=['advance_id'=>$advance->id,'amount'=>$this->pay->money($amount),'outstanding_before'=>$this->pay->money($balance)];$components[]=['name'=>'Advance #'.$advance->id.' recovery','kind'=>'recovery','amount'=>$this->pay->money($amount)];$recover+=$amount;}}$net=$gross-$deduct-$recover;$row=['staff_profile_id'=>$p->id,'membership_id'=>$p->membership_id,'employee_no'=>$p->employee_no,'name'=>$p->name,'designation'=>$p->designation,'salary_structure_id'=>(int)array_key_first($segments),'salary_segments'=>$segments,'gross_amount'=>$this->pay->money($gross),'deduction_amount'=>$this->pay->money($deduct),'advance_recovery'=>$this->pay->money($recover),'net_amount'=>$this->pay->money($net),'components'=>$components,'advance_plans'=>$plans,'attendance'=>$counts,'attendance_sources'=>$sourceDays,'policy_version'=>$policy->version,'policy_rules'=>$rules,'school_name'=>$school->name,'school_code'=>$school->code,'campus_name'=>$c->name,'period'=>$start];$rows[]=$row;$grossTotal+=$gross;$deductTotal+=$deduct;$recoverTotal+=$recover;$netTotal+=$net;}
  $source=['policy_id'=>$policy->id,'policy_version'=>$policy->version,'rows'=>$rows];return ['campus_id'=>$campus,'month'=>$month,'period'=>$start,'policy'=>$policy,'rules'=>$rules,'rows'=>$rows,'source_digest'=>hash('sha256',json_encode($source)),'run_id'=>$existing?->id??0,'lock_version'=>$existing?->lock_version??0,'totals'=>['gross'=>$this->pay->money($grossTotal),'deductions'=>$this->pay->money($deductTotal),'recoveries'=>$this->pay->money($recoverTotal),'net'=>$this->pay->money($netTotal)]];}
 public function generate(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.manage');$preview=$this->preview($r,$d['campus_id'],$d['month']);if($preview['source_digest']!==$d['source_digest']||$preview['run_id']!=$d['run_id']||$preview['lock_version']!=$d['lock_version'])$this->pay->fail('Payroll inputs or the draft changed. Refresh the preview before generating.');$id=$preview['run_id'];$header=['status'=>'draft','lock_version'=>$preview['lock_version']+1,'source_digest'=>$preview['source_digest'],'snapshot'=>json_encode(['totals'=>$preview['totals'],'policy_id'=>$preview['policy']->id,'policy_rules'=>$preview['rules']]),'updated_at'=>now()];if($id){$ids=DB::table('payroll_items')->where('school_id',$sid)->where('payroll_run_id',$id)->pluck('id');if(DB::table('salary_payment_allocations')->where('school_id',$sid)->whereIn('payroll_item_id',$ids)->exists()||DB::table('advance_recoveries')->where('school_id',$sid)->whereIn('payroll_item_id',$ids)->exists())$this->pay->fail('This legacy draft has linked payments/recoveries; reconcile it before recalculating.');DB::table('payroll_item_components')->where('school_id',$sid)->whereIn('payroll_item_id',$ids)->delete();DB::table('payroll_items')->where('school_id',$sid)->where('payroll_run_id',$id)->whereNotIn('staff_profile_id',array_column($preview['rows'],'staff_profile_id'))->delete();DB::table('payroll_runs')->where('school_id',$sid)->where('id',$id)->update($header);}else $id=DB::table('payroll_runs')->insertGetId($header+['school_id'=>$sid,'campus_id'=>$d['campus_id'],'period'=>$preview['period'],'revision'=>1,'created_at'=>now()]);foreach($preview['rows'] as $row){$key=['school_id'=>$sid,'payroll_run_id'=>$id,'staff_profile_id'=>$row['staff_profile_id']];DB::table('payroll_items')->updateOrInsert($key,['salary_structure_id'=>$row['salary_structure_id'],'gross_amount'=>$row['gross_amount'],'deduction_amount'=>$row['deduction_amount'],'advance_recovery'=>$row['advance_recovery'],'net_amount'=>$row['net_amount'],'snapshot'=>json_encode($row,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);$item=DB::table('payroll_items')->where($key)->value('id');foreach($row['components'] as $component)DB::table('payroll_item_components')->insert($component+['school_id'=>$sid,'payroll_item_id'=>$item,'created_at'=>now(),'updated_at'=>now()]);}$this->pay->access->audit($r,'payroll.draft_generated','payroll_runs',$id,['source_digest'=>$preview['source_digest'],'totals'=>$preview['totals']]);return ['id'=>$id,'message'=>'Payroll draft generated. No payment or advance recovery has been posted.'];});}
 public function approve(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->pay->lock($r,'payroll.approve');$run=DB::table('payroll_runs')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$this->pay->campus($r,$run->campus_id,true);if($run->status!=='draft'||$run->lock_version!=$d['lock_version']||!$run->source_digest)$this->pay->fail('Reload a current, generated payroll draft before approving.');$preview=$this->preview($r,$run->campus_id,substr($run->period,0,7),$id);if($preview['source_digest']!==$run->source_digest)$this->pay->fail('Salary, attendance, policy or advances changed. Recalculate the draft before approval.');$items=DB::table('payroll_items')->where('school_id',$sid)->where('payroll_run_id',$id)->get();foreach($items as $item){$snapshot=json_decode($item->snapshot,true);foreach($snapshot['advance_plans']??[] as $plan)DB::table('advance_recoveries')->insert(['school_id'=>$sid,'staff_advance_id'=>$plan['advance_id'],'payroll_item_id'=>$item->id,'amount'=>$plan['amount'],'created_at'=>now(),'updated_at'=>now()]);}$meta=json_decode($run->snapshot,true);$meta['approved_by_name']=$r->user()->name;DB::table('payroll_runs')->where('school_id',$sid)->where('id',$id)->update(['status'=>'approved','approved_by'=>$this->pay->access->membership($r)->id,'approved_at'=>now(),'snapshot'=>json_encode($meta),'lock_version'=>$run->lock_version+1,'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.approved','payroll_runs',$id,['totals'=>$preview['totals'],'source_digest'=>$run->source_digest]);return ['message'=>'Payroll approved. Payslips and outstanding salary are now available.'];});}
